function validate([s, sub, mappings]) {
  const ok = /^[A-Za-z0-9]+$/;
  if (typeof s !== 'string' || typeof sub !== 'string') return 's and sub must be strings.';
  if (sub.length < 1 || sub.length > s.length || s.length > 5000) return 'Need 1 <= sub.length <= s.length <= 5000.';
  if (!ok.test(s) || !ok.test(sub)) return 's and sub use only letters and digits.';
  if (!Array.isArray(mappings) || mappings.length > 1000) return 'mappings holds at most 1000 pairs.';
  for (const pair of mappings) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each mapping is a pair [old, new].';
    if (pair.some(c => typeof c !== 'string' || c.length !== 1 || !ok.test(c))) return 'Mapping characters are single letters or digits.';
    if (pair[0] === pair[1]) return 'A mapping must change the character (old != new).';
  }
  return null;
}

