function matchReplacement(s, sub, mappings) {
  const canBecome = new Map();
  for (const [from, to] of mappings) {
    if (!canBecome.has(from)) {
      canBecome.set(from, new Set());
    }
    canBecome.get(from).add(to);
  }

  for (let start = 0; start + sub.length <= s.length; start++) {
    let matches = true;
    for (let j = 0; j < sub.length; j++) {
      const want = sub[j];
      const have = s[start + j];
      if (want !== have && !canBecome.get(want)?.has(have)) {
        matches = false;
        break;
      }
    }
    if (matches) {
      return true;
    }
  }
  return false;
}

