function matchReplacement(s, sub, mappings) {
  // Turn each character of sub into a character class of everything it may become, then search s.
  let pattern = '';
  for (const c of sub) {
    let options = c;
    for (const pair of mappings) if (pair[0] === c) options += pair[1];
    pattern += '[' + options + ']';
  }
  return new RegExp(pattern).test(s);
}

