function generate(rand, size) {
  const large = size === 'large';
  const pick = text => text[Math.floor(rand() * text.length)];
  const every = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const alphabet = large ? pick(['ab', 'aAbB01', 'abcxyz', every]) : pick(['ab', 'ab01', 'aAb']);
  const pairPool = large ? (rand() < 0.5 ? alphabet : every) : 'ab01A';
  const n = large ? 4000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 9);
  const s = Array.from({ length: n }, () => pick(alphabet)).join('');
  const m = large ? 1 + Math.floor(rand() * Math.min(n, 2500)) : 1 + Math.floor(rand() * n);
  const k = large ? Math.floor(rand() * 1001) : Math.floor(rand() * 5);
  const mappings = [];
  while (mappings.length < k) {
    const from = pick(pairPool), to = pick(pairPool);
    if (from !== to) mappings.push([from, to]);
  }
  // Copy a window of s, then undo some replacements so that a match exists unless we spoil it.
  const start = Math.floor(rand() * (n - m + 1));
  const chars = s.slice(start, start + m).split('');
  const sources = new Map();
  for (const [from, to] of mappings) { if (!sources.has(to)) sources.set(to, []); sources.get(to).push(from); }
  for (let j = 0; j < m; j++) {
    const options = sources.get(chars[j]);
    if (options && rand() < 0.5) chars[j] = pick(options);
  }
  const spoil = rand() < 0.45 ? 1 + Math.floor(rand() * (large ? 3 : 1)) : 0;
  for (let t = 0; t < spoil; t++) chars[Math.floor(rand() * m)] = pick(every);
  return [s, chars.join(''), mappings];
}
